  if (valType === "function") {
    return { body: `${(val as () => unknown).name}()` };
  }

  return { body: val as BodyInit };
}

function nullBody(method: string, status: number | undefined): boolean | 0 | undefined {
  // prettier-ignore
  return (method === "HEAD" ||
    status === 100 || status === 101 || status === 102 ||
    status === 204 || status === 205 || status === 304
  );
}

function errorResponse(error: HTTPError, config: H3Config, errHeaders?: Headers): Response {
  const { debug, problemDetails } = config;
  const baseHeaders = problemDetails ? problemHeaders : jsonHeaders;
  let headers: Headers = error.headers
    ? mergeHeaders(baseHeaders, error.headers)
    : new Headers(baseHeaders);
  if (errHeaders) {
    headers = mergeHeaders(headers, errHeaders);
  }
  return new FastResponse(
    JSON.stringify(
      problemDetails
        ? problemBody(error, debug)
        : {
            ...error.toJSON(),
            stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
          },
      undefined,
      debug ? 2 : undefined,
    ),
    {
      status: error.status,
      statusText: error.statusText,
      headers,
    },
  );
}

